#!/usr/bin/env bash
# iOS simulator build without code signing, for every stack Jaglosky supports:
# - Flutter (pubspec.yaml)        → flutter build ios --simulator --debug (simulator builds are debug-only in Flutter)
# - Expo CNG (no committed ios/)  → expo prebuild → pod install → xcodebuild Release (JS bundle inside)
# - React Native / native Xcode   → [pod install if there is a Podfile] → xcodebuild (workspace or project, shared scheme)
# Output: $OUT/app-path.txt (path to the .app) or $OUT/build-result.txt = fail + logs.
set -uo pipefail
OUT="$1"
mkdir -p "$OUT"
fail() { echo "$1" >> "$OUT/notes.txt"; echo fail > "$OUT/build-result.txt"; echo "❌ $1"; exit 0; }
done_ok() {
  [ -n "$1" ] && [ -d "$1" ] || fail "no .app after the build"
  (cd "$(dirname "$1")" && echo "$PWD/$(basename "$1")") > "$OUT/app-path.txt"
  echo ok > "$OUT/build-result.txt"
  echo "iOS build ($2): $(( ($(date +%s) - START) / 60 )) min ($(cat "$OUT/xcode.txt"))" | tee -a "$OUT/notes.txt"
  exit 0
}

# Xcode: the newest one installed on the runner (App Store requires Xcode 26+ for uploads), or JAGLOSKY_XCODE
# (e.g. 16.4 for an app that does not build on Xcode 26 yet — a simulator build only, uploads still need 26).
newest_xcode() { ls -d /Applications/Xcode_${1}*.app 2>/dev/null | awk -F'Xcode_|\\.app' '{print $2" "$0}' | grep -E '^[0-9]' | sort -V | tail -1 | cut -d' ' -f2-; }
ls -d /Applications/Xcode_*.app 2>/dev/null | sed 's#.*/##' | tr '\n' ' ' > "$OUT/xcodes-available.txt"
XC="$(newest_xcode "${JAGLOSKY_XCODE:-}")"
if [ -n "${JAGLOSKY_XCODE:-}" ] && [ -z "$XC" ]; then
  echo "⚠️  Xcode ${JAGLOSKY_XCODE} is not on this runner ($(cat "$OUT/xcodes-available.txt")) — using the newest" | tee -a "$OUT/notes.txt"
  XC="$(newest_xcode "")"
fi
[ -n "$XC" ] && sudo xcode-select -s "$XC/Contents/Developer"
xcodebuild -version | head -2 | tr '\n' ' ' | tee "$OUT/xcode.txt"; echo

export CI=1 EXPO_NO_TELEMETRY=1 EXPO_NO_GIT_STATUS=1 SENTRY_DISABLE_AUTO_UPLOAD=true
START=$(date +%s)

# --- Flutter ---------------------------------------------------------------------------------
if [ -f pubspec.yaml ] && grep -qE '^\s*(flutter:|sdk:\s*flutter)' pubspec.yaml; then
  echo "▸ flutter build ios --simulator --debug"
  { flutter --version && flutter pub get && flutter build ios --simulator --debug --no-codesign; } > "$OUT/flutter-build.log" 2>&1 \
    || { tail -30 "$OUT/flutter-build.log"; fail "flutter build ios failed (flutter-build.log)"; }
  done_ok "$(ls -d build/ios/iphonesimulator/*.app 2>/dev/null | head -1)" "Flutter, debug"
fi

# --- Expo CNG: ios/ generated by prebuild --------------------------------------------------------
if [ -f package.json ] && grep -q '"expo"' package.json && { [ ! -d ios ] || git check-ignore -q ios/Podfile 2>/dev/null; }; then
  echo "▸ expo prebuild --platform ios"
  NODE_ENV=production npx --no-install expo prebuild --platform ios --no-install --clean > "$OUT/prebuild.log" 2>&1 \
    || { tail -20 "$OUT/prebuild.log"; fail "expo prebuild (iOS) failed"; }
fi

# --- Xcode project: ios/ (RN, Expo) or the repo root (native) --------------------------------------
DIR=.
ls -d ios/*.xcodeproj > /dev/null 2>&1 && DIR=ios
if [ -f "$DIR/Podfile" ]; then
  echo "▸ pod install ($DIR)"
  (cd "$DIR" && pod install) > "$OUT/pods.log" 2>&1 || { tail -30 "$OUT/pods.log"; fail "pod install failed"; }
fi

WS="$(ls -d "$DIR"/*.xcworkspace 2>/dev/null | head -1)"
PROJ="$(ls -d "$DIR"/*.xcodeproj 2>/dev/null | head -1)"
if [ -n "$WS" ]; then CONTAINER=(-workspace "$WS"); NAME="$(basename "$WS" .xcworkspace)"
elif [ -n "$PROJ" ]; then CONTAINER=(-project "$PROJ"); NAME="$(basename "$PROJ" .xcodeproj)"
else fail "no .xcworkspace or .xcodeproj (in ios/ or the repo root)"
fi

# Scheme: the one named like the project, otherwise the first one that is not a test/Pods scheme.
SCHEME="$(xcodebuild "${CONTAINER[@]}" -list -json 2>/dev/null | NAME="$NAME" python3 -c '
import json, os, sys
d = json.load(sys.stdin); d = d.get("workspace") or d.get("project") or {}
schemes = d.get("schemes", [])
name = os.environ["NAME"]
pick = name if name in schemes else next((s for s in schemes if not s.startswith("Pods") and not s.endswith("Tests")), "")
print(pick)')"
[ -n "$SCHEME" ] || fail "no shared Xcode scheme (xcodebuild -list)"

DD="${RUNNER_TEMP:-/tmp}/jaglosky-ios-dd"
echo "▸ xcodebuild $SCHEME (Release, iphonesimulator)"
if ! NODE_ENV=production xcodebuild "${CONTAINER[@]}" -scheme "$SCHEME" -configuration Release -sdk iphonesimulator \
  -destination 'generic/platform=iOS Simulator' -derivedDataPath "$DD" \
  CODE_SIGNING_ALLOWED=NO COMPILER_INDEX_STORE_ENABLE=NO ONLY_ACTIVE_ARCH=YES \
  > "$OUT/xcodebuild.log" 2>&1; then
  grep -E "error:|\*\* BUILD FAILED" "$OUT/xcodebuild.log" | head -20
  fail "xcodebuild failed (xcodebuild.log)"
fi
done_ok "$(ls -d "$DD"/Build/Products/Release-iphonesimulator/*.app 2>/dev/null | head -1)" "$SCHEME, Release"
